{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "U-47700, which shares the 3,4-dichlorophenyl and cyclohexane core with the query, was detected in zebrafish brain after only 20 min of exposure, demonstrating that this scaffold can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A primary carboxamide analogue containing the 3,4-dichlorophenyl motif achieved a CSF:free plasma ratio of 1:1 in rats, showing that a primary amide is compatible with excellent CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "AH-7921, a 3,4-dichlorophenyl amide with a cyclohexane core, showed a brain-to-plasma ratio of 16.6 in rats, indicating strong brain uptake for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Sertraline, which shares the dichlorophenyl and cyclohexane-like hydrophobic scaffold, is concentrated 20- to 50-fold in brain versus blood, supporting CNS access for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A kappa agonist with a dichlorophenylacetamide and cyclohexane/piperazine framework showed high brain uptake in rat PET studies, further supporting CNS penetration for dichlorophenyl amide-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A dichlorophenyl-containing compound with multiple polar groups still exhibited good BBB penetration with measurable brain concentrations after oral dosing, indicating that polar functionality does not automatically preclude CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a neutral, moderately lipophilic cyclohexane dicarboxamide bearing a 3,4-dichloroanilide. Multiple analogues sharing the dichlorophenyl/cyclohexane amide motif show robust brain penetration, and primary carboxamide analogues retain excellent CNS exposure. Although the query lacks a basic amine and has a TPSA near 72, no strong efflux liability is evident, so meaningful CNS access is likely.",
  "evidence_gaps": [
    "No direct brain, plasma, CSF, or perfusion measurement exists for the exact query molecule.",
    "Most supportive analogues contain a basic amine that is absent in the query, so the contribution of basicity to brain uptake is uncertain.",
    "Efflux transporter susceptibility of the query has not been experimentally assessed.",
    "Stereochemistry-specific pharmacokinetic data are not available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

